def parse_qsl_(qs):
    def decode_percent(s):
        result = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '%' and i + 2 < n:
                hex_chars = s[i+1:i+3]
                try:
                    byte_val = int(hex_chars, 16)
                    result.append(chr(byte_val))
                    i += 3
                except ValueError:
                    result.append(c)
                    i += 1
            else:
                result.append(c)
                i += 1
        return ''.join(result)

    def decode_plus_and_percent(s):
        # Replace '+' with space first, then decode percent escapes
        s = s.replace('+', ' ')
        return decode_percent(s)

    if not qs:
        return []

    # Split by '&' only
    parts = qs.split('&')
    result = []
    for part in parts:
        if part == '':
            continue
        # Find first '='
        eq_pos = part.find('=')
        if eq_pos == -1:
            key = decode_plus_and_percent(part)
            value = ''
        else:
            key = decode_plus_and_percent(part[:eq_pos])
            value = decode_plus_and_percent(part[eq_pos+1:])
        result.append((key, value))

    return result
